  1	/**
  2	 * Tests for handleGetRunMetadata in gui/api.ts — WP-002 (handler-level)
  3	 * and GET /api/projects/:repo/:slug/run-metadata in gui/server.ts — WP-002 (namespaced HTTP route)
  4	 *
  5	 * Acceptance criteria (handler-level):
  6	 *   AC-1: GET /api/projects/:slug/run-metadata returns HTTP 200 with parsed
  7	 *         metadata JSON when the file exists.
  8	 *   AC-2: Returns HTTP 404 when the metadata file does not exist on disk.
  9	 *   AC-3: Returns HTTP 404 when the project has no meta.plan_path in the
 10	 *         ledger (project not found).
 11	 *   AC-4: Rejects an unsafe slug with HTTP 400 (path-traversal guard via
 12	 *         assertSafeSlug() — surfaced as NOT_FOUND per helper convention).
 13	 *   AC-5: File path is constructed as path.join(planPath, '.orchestrator-run.json')
 14	 *         where planPath is the stored meta.plan_path value.
 15	 *
 16	 * Acceptance criteria (namespaced HTTP route — WP-002 rework):
 17	 *   AC-NS-1: GET /api/projects/:repo/:slug/run-metadata returns the same JSON as
 18	 *            GET /api/projects/:slug/run-metadata for a valid namespaced project.
 19	 *   AC-NS-2: Returns 404 for unknown repo/slug combinations (no .meta.json).
 20	 *   AC-NS-3: Returns 404 for path-traversal attempts in repo or slug segments.
 21	 *
 22	 * Uses real temp directories and LedgerStore to seed fixture data.
 23	 */
 24	
 25	import { describe, it, expect, beforeEach, afterEach } from 'vitest';
 26	import { createServer } from 'node:http';
 27	import type { Server } from 'node:http';
 28	import { mkdtemp, rm, writeFile, mkdir } from 'fs/promises';
 29	import { join } from 'path';
 30	import { tmpdir } from 'os';
 31	
 32	import { handleGetRunMetadata, ApiError } from '../../gui/api.js';
 33	import { handleRequest } from '../../gui/server.js';
 34	import { LedgerStore } from '../../src/storage/ledger-store.js';
 35	import { now } from '../../src/utils/timestamp.js';
 36	import type { RootIndex } from '../../src/schema/root-index.js';
 37	
 38	// ---------------------------------------------------------------------------
 39	// Fixture helpers
 40	// ---------------------------------------------------------------------------
 41	
 42	function makeRoot(overrides: Partial<RootIndex> = {}): RootIndex {
 43	  return {
 44	    plan_file: 'plan.md',
 45	    date_created: now(),
 46	    last_updated: now(),
 47	    status: 'IN_PROGRESS',
 48	    total_work_packages: 0,
 49	    pending_work_packages: 0,
 50	    work_packages: [],
 51	    project_comments: [],
 52	    ...overrides,
 53	  };
 54	}
 55	
 56	async function createProject(
 57	  ledgerRoot: string,
 58	  slug: string,
 59	  rootOverrides: Partial<RootIndex> = {}
 60	): Promise<LedgerStore> {
 61	  const planPath = join(tmpdir(), slug);
 62	  const store = new LedgerStore(planPath, ledgerRoot);
 63	  await store.writeRootIndex(makeRoot(rootOverrides));
 64	  return store;
 65	}
 66	
 67	// ---------------------------------------------------------------------------
 68	// Suite
