214	/**
215	 * Aggregates all project_comments from every project ledger into a single
216	 * flat array, sorted by timestamp descending (newest first).
217	 * Per-project read failures are logged to stderr and skipped gracefully.
218	 * Returns an empty array when no projects exist or no comments are found.
219	 */
220	export async function handleGetInsights(ledgerRoot: string): Promise<InsightEntry[]> {
221	  const projects = await LedgerStore.listAllProjects(ledgerRoot);
222	
223	  const entries: InsightEntry[] = [];
224	
225	  await Promise.all(
226	    projects.map(async (meta) => {
227	      const store = new LedgerStore(meta.plan_path, ledgerRoot);
228	      let rootIndex;
229	      try {
230	        rootIndex = await store.readRootIndex();
231	      } catch (err) {
232	        process.stderr.write(
233	          `[handleGetInsights] Skipping project "${meta.slug}": ${String(err)}\n`
234	        );
235	        return;
236	      }
237	
238	      const comments = rootIndex.project_comments;
239	      if (!comments || comments.length === 0) return;
240	
241	      for (const comment of comments) {
242	        entries.push({
243	          project_slug: meta.slug,
244	          project_status: meta.status,
245	          ...comment,
246	        });
247	      }
248	    })
249	  );

